import React, { useState, useEffect } from 'react';
import toast from 'react-hot-toast';
import { getPartyEmails, updatePartyEmail } from '../services/api';
import { Edit2, Save, Lock } from 'lucide-react';

export default function PartyEmailEditor() {
  const [parties, setParties] = useState([]);
  const [selected, setSelected] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [fetching, setFetching] = useState(true);

  useEffect(() => {
    getPartyEmails()
      .then(res => setParties(res.data.data || []))
      .catch(() => toast.error('Failed to load party emails'))
      .finally(() => setFetching(false));
  }, []);

  const handleSelect = (partyCode) => {
    setSelected(partyCode);
    const party = parties.find(p => p.partyCode === partyCode);
    setNewEmail(party?.email || '');
    setPassword('');
  };

  const handleUpdate = async () => {
    if (!selected) return;
    if (!password) return toast.error('Please enter password to confirm');
    const party = parties.find(p => p.partyCode === selected);
    if (!party) return;
    setLoading(true);
    try {
      await updatePartyEmail(party._id, newEmail, password);
      toast.success(`Email updated for ${selected}`);
      setParties(prev =>
        prev.map(p => p.partyCode === selected ? { ...p, email: newEmail } : p)
      );
      setSelected('');
      setPassword('');
    } catch (err) {
      toast.error(err.response?.data?.message || 'Update failed');
    } finally {
      setLoading(false);
    }
  };

  if (fetching) return <div className="loading-text">Loading party list…</div>;

  return (
    <div className="email-editor">
      <div className="form-row">
        <div className="form-group flex-1">
          <label>Select Party to Edit</label>
          <select
            value={selected}
            onChange={e => handleSelect(e.target.value)}
            className="select-input"
          >
            <option value="">— Select Party —</option>
            {parties.map(p => (
              <option key={p._id} value={p.partyCode}>
                {p.partyName} ({p.partyCode})
              </option>
            ))}
          </select>
        </div>
      </div>

      {selected && (
        <div className="form-row">
          <div className="form-group flex-1">
            <label><Edit2 size={14} /> Email Address(es)</label>
            <input
              type="text"
              value={newEmail}
              onChange={e => setNewEmail(e.target.value)}
              placeholder="email1@example.com, email2@example.com"
            />
            <small>Separate multiple emails with commas</small>
          </div>
          <div className="form-group">
            <label><Lock size={14} /> Confirm Password</label>
            <input
              type="password"
              value={password}
              onChange={e => setPassword(e.target.value)}
              placeholder="Enter password"
            />
          </div>
          <div className="form-group align-end">
            <button
              className="btn btn-primary"
              onClick={handleUpdate}
              disabled={loading}
            >
              {loading ? <span className="spinner-sm" /> : <Save size={16} />}
              {loading ? 'Saving…' : 'Update Email'}
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
